import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"既濟","description":"焦氏易林注 - 既濟","frontmatter":{"title":"既濟","description":"焦氏易林注 - 既濟"},"headers":[],"relativePath":"zh/classics/jiaoyilin/063.md","filePath":"zh/classics/jiaoyilin/063.md"}'),l={name:"zh/classics/jiaoyilin/063.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="既濟" tabindex="-1">既濟 <a class="header-anchor" href="#既濟" aria-label="Permalink to “既濟”">​</a></h1><h3 id="既濟-1" tabindex="-1">既濟 <a class="header-anchor" href="#既濟-1" aria-label="Permalink to “既濟”">​</a></h3><h3 id="既濟之乾" tabindex="-1">既濟之乾 <a class="header-anchor" href="#既濟之乾" aria-label="Permalink to “既濟之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>游駒石門，騄耳安全。受福西鄰，歸隱玉泉。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為門、為石、為馬，故曰游駒石門、曰騄耳。坎為西鄰、為泉，乾為玉。○隱，宋元本作邑，依汲古。</p><h3 id="既濟之坤" tabindex="-1">既濟之坤 <a class="header-anchor" href="#既濟之坤" aria-label="Permalink to “既濟之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>陽春草生，萬物風興。君子所居，禍災不到。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為茅茹，故曰草、曰萬物。坤為風、為禍災。○風，宋元本作盛，依汲古。坤為風失傳象。</p><h3 id="既濟之屯" tabindex="-1">既濟之屯 <a class="header-anchor" href="#既濟之屯" aria-label="Permalink to “既濟之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>人無足，法緩除。牛出雄，走羊驚。不失其家。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>前四句三字句，末四字句。震為人、為足，伏巽，下斷，故曰無足。坎為法律。除，授官也。坤柔，故曰緩除，言人有疾不能授官也。坤為牛，震為出、為雄、為羊、為驚。艮為家。家，音姑，與除韻。○緩，汲古作紱，依宋元本。牛，宋元本作才，依汲古。</p><h3 id="既濟之蒙" tabindex="-1">既濟之蒙 <a class="header-anchor" href="#既濟之蒙" aria-label="Permalink to “既濟之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>泰山上奔，變見太微。陳吳廢忽，作為禍患。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為山，震東，故曰泰山。泰山，東嶽也。震為奔，艮為星，故曰太微。坤坎皆在北。太微，北極星也。陳吳，皆訛字，疑吳為突之形訛，陳為臣之音訛，言祭仲臣突廢忽也，事見《左傳桓十一年》突，鄭厲公；忽，鄭昭公。坤為臣，坎為禍患。○山，元本作上，上作止，依宋本、汲古。吳，汲古作吾，微作傲，依宋元本。</p><h3 id="既濟之需" tabindex="-1">既濟之需 <a class="header-anchor" href="#既濟之需" aria-label="Permalink to “既濟之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>乘龍吐光，先暗後明。燎獵大得，六師以昌。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為龍，離為光，互兌口，故曰吐光。坎為暗，離為明、為燎，坎數六，坎眾，故曰六師以昌。言文王因獵得太公也。○第二句宋元本先作使，依汲古。後，宋本、汲古作復，依元本。又吐光，汲古作光土，六作太，均依宋元本。《山海經》天不足西北，有龍銜燭照天門。</p><h3 id="既濟之訟" tabindex="-1">既濟之訟 <a class="header-anchor" href="#既濟之訟" aria-label="Permalink to “既濟之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>羊頭兔足，羸瘦少肉。漏囊敗粟，利無所得。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《恆》。</p><h3 id="既濟之師" tabindex="-1">既濟之師 <a class="header-anchor" href="#既濟之師" aria-label="Permalink to “既濟之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>因禍受福，喜盈其室。螟蟲不作，君無苛忒。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為禍，震為福、為喜，坎為室。巽為螟蟲，巽伏，故曰不作。震為君，坤為苛忒，震解，故無。○苛忒，宋元本訛可得，依汲古。</p><h3 id="既濟之比" tabindex="-1">既濟之比 <a class="header-anchor" href="#既濟之比" aria-label="Permalink to “既濟之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>舜升大禹，石夷之野。徵詣王庭，拜治水土。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>王庭，汲古作黃門，依《乾》之《中孚》。</p><h3 id="既濟之小畜" tabindex="-1">既濟之小畜 <a class="header-anchor" href="#既濟之小畜" aria-label="Permalink to “既濟之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>烏子鵲雛，常與母俱。顧類群族，不離其巢。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>伏艮為鳥，震為鵲。坤為母、為群、為族類。艮為巢。○族，汲古作聚，依宋元本。</p><h3 id="既濟之履" tabindex="-1">既濟之履 <a class="header-anchor" href="#既濟之履" aria-label="Permalink to “既濟之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>夷羿所射，發輒有獲。矰加鵲鷹，雙鳥俱得。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>元本註：夷羿，古之善射者。伏震為射，坎為獲。系繳於矢曰矰。巽為矰。艮為鷹，震為鵲，坤數二，故曰雙鳥。○矰，汲古訛增，鵲作倉，俱依宋元本。</p><h3 id="既濟之泰" tabindex="-1">既濟之泰 <a class="header-anchor" href="#既濟之泰" aria-label="Permalink to “既濟之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>晨風文翰，大興就溫。昧過我邑，羿無所得。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《革》。文翰，鳥也。</p><h3 id="既濟之否" tabindex="-1">既濟之否 <a class="header-anchor" href="#既濟之否" aria-label="Permalink to “既濟之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>六喜三福，南至歡國。與喜同樂，嘉我潔德。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為喜福，數六，艮數三，故曰六喜三福。乾為南，坤為國，乾為金玉，故曰潔德。○同，宋本作忻，嘉作圭，均依汲古。</p><h3 id="既濟之同人" tabindex="-1">既濟之同人 <a class="header-anchor" href="#既濟之同人" aria-label="Permalink to “既濟之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>鬬龍股折，日遂不明。自外為主，弟伐其兄。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>《左傳莊十四年》內蛇與外蛇鬬於鄭南門中，內蛇死，後宋人劫祭仲，納厲公，所謂自外為主也。厲公入，昭公出奔，所謂弟伐其兄也。同人巽為股，伏震為龍，坎為折，故曰折股。離為日，在下，故不明。震為主、為兄，坎為震弟。</p><h3 id="既濟之大有" tabindex="-1">既濟之大有 <a class="header-anchor" href="#既濟之大有" aria-label="Permalink to “既濟之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>蒙慶受福，有所獲得，不利出域。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為民，拱向九五，故曰有獲。坤為域，坤閉，故不利出域。○域，宋元本作門，非，依汲古。</p><h3 id="既濟之謙" tabindex="-1">既濟之謙 <a class="header-anchor" href="#既濟之謙" aria-label="Permalink to “既濟之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>蠻夷戎狄，太陰所積。涸冰冱寒，君子不存。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳前《師》之《巽》。</p><h3 id="既濟之豫" tabindex="-1">既濟之豫 <a class="header-anchor" href="#既濟之豫" aria-label="Permalink to “既濟之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>畏昏潛處，候旦昭明。卒逢白日，為世榮主。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《中孚》。世榮，依校，各本皆作榮祿。</p><h3 id="既濟之隨" tabindex="-1">既濟之隨 <a class="header-anchor" href="#既濟之隨" aria-label="Permalink to “既濟之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>水流趨下，欲至東海。求我所有，買鮪與鯉。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《無妄》。</p><h3 id="既濟之蠱" tabindex="-1">既濟之蠱 <a class="header-anchor" href="#既濟之蠱" aria-label="Permalink to “既濟之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>冠帶南行，與福喜期。徼於嘉國，拜位逢時。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>○拜位，依《坎》之《井》校，宋元本作拜為，汲古作釋為，均非。</p><h3 id="既濟之臨" tabindex="-1">既濟之臨 <a class="header-anchor" href="#既濟之臨" aria-label="Permalink to “既濟之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>莎雞振羽，為季門戶。新沐彈冠，仲父悅喜。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>莎雞，蟋蟀也。《詩豳風》六月莎雞振羽。伏艮為季，坤為門戶、為疑為在之訛，言莎雞在季門戶也。《詩》九月在戶是其證。伏艮為冠，艮手，故曰彈冠。仲父，管仲也。管仲初至，齊桓公為三熏三沐，然後見，即以為相。震為樂，乾為父，故曰仲父悅喜。</p><h3 id="既濟之觀" tabindex="-1">既濟之觀 <a class="header-anchor" href="#既濟之觀" aria-label="Permalink to “既濟之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>結衿流粥，遭讒桎梏。周召述職，身受大福。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為衿、為結、為漿，故曰粥。伏震為周召，坤為身。按：管子初見桓公，絀纓捷衽，使人操斧，結衿，即捷衽，罪人之服也。粥鬻通，養也。結衿流粥者，言得罪而流寓在外也。周召者，周召公也。《揚子法言先知篇》雲召公述職，蔽芾甘棠，言甘棠詩為召公述職時，聽訟樹下也。身受大福者，言罪人蒙召公思得釋也。蓋魯韓詩說祇言聽訟，齊說兼平反冤獄也。○粥，汲古作弼，局本作溺，茲從宋元本，但仍恐有訛字。</p><h3 id="既濟之噬嗑" tabindex="-1">既濟之噬嗑 <a class="header-anchor" href="#既濟之噬嗑" aria-label="Permalink to “既濟之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>田鼠野雞，意常欲逃。拘制籠檻，不得動搖。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《隨》。</p><h3 id="既濟之賁" tabindex="-1">既濟之賁 <a class="header-anchor" href="#既濟之賁" aria-label="Permalink to “既濟之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>居華巔，觀浮雲。風不搖，雨不濡。心平安，無咎憂。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為華顛，為觀，坎為雲。伏巽為風，坎為雨，風雨皆在山下，故不被其禍。坎為心、為憂。○三字句，依宋元本。不，元本作之，依宋本，汲古作&quot;居華山巔，游觀浮雲。有雨不濡，心樂無憂&quot;作四字句，皆後人妄改，非。</p><h3 id="既濟之剝" tabindex="-1">既濟之剝 <a class="header-anchor" href="#既濟之剝" aria-label="Permalink to “既濟之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>傾倚將顛，亂不能存。英雄作業，家困無年。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>陽窮上反下，故曰將顛。坤為亂、為亡，故不能存。艮為家，坤為年，坤喪，故無年。○亂不能存，宋本作不能得存，依汲古。</p><h3 id="既濟之復" tabindex="-1">既濟之復 <a class="header-anchor" href="#既濟之復" aria-label="Permalink to “既濟之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>心愿所喜，今乃逢時。保我利福，不離兵革。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《兌》之《蹇》。</p><h3 id="既濟之無妄" tabindex="-1">既濟之無妄 <a class="header-anchor" href="#既濟之無妄" aria-label="Permalink to “既濟之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>靈龜陸處，盤桓失所。阿衡退耕，夏封於國。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為龜、為陸，艮止，故盤桓。巽為衡、為夏，坤為國，故曰夏封於國。○夏，元本作憂，依宋本、汲古。</p><h3 id="既濟之大畜" tabindex="-1">既濟之大畜 <a class="header-anchor" href="#既濟之大畜" aria-label="Permalink to “既濟之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>弱水之右，有西王母。生不知老，與天相保。不利行旅。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>伏坤為水，坤柔，故曰弱水。互兌為右、為西，伏坤為母，乾為王，故曰王母。乾為老、為天，震為行旅，兌折，故不利。元註：柳宗元曰：西海之山有王母，神山所居，其下有水，散渙無力，不能負芥。</p><h3 id="既濟之頤" tabindex="-1">既濟之頤 <a class="header-anchor" href="#既濟之頤" aria-label="Permalink to “既濟之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>抱瑰求金，日暮坐吟。終月卒歲，竟無成功。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>瑰，《說文》珠也。震為珠，艮為抱、為求、為金，抱瑰求金，必不能得，故日暮坐吟也。艮為日，坤為暮，震為吟，伏兌為月，坤為歲，艮為終，故曰終月卒歲。坤喪，故無功。○月，汲古作身，依宋元本。</p><h3 id="既濟之大過" tabindex="-1">既濟之大過 <a class="header-anchor" href="#既濟之大過" aria-label="Permalink to “既濟之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>言笑未畢，憂來暴卒。身加檻纜，囚系縛束。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《大過》。○檻纜，宋本作扼檻，元本作扼攬，茲依汲古。</p><h3 id="既濟之坎" tabindex="-1">既濟之坎 <a class="header-anchor" href="#既濟之坎" aria-label="Permalink to “既濟之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>望幸不至，文章未成。王子逐兔，犬踦不得。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《既濟》。</p><h3 id="既濟之離" tabindex="-1">既濟之離 <a class="header-anchor" href="#既濟之離" aria-label="Permalink to “既濟之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>震悚恐懼，多所畏忌。行道留難，不可以步。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳前《蒙》之《渙》。</p><h3 id="既濟之咸" tabindex="-1">既濟之咸 <a class="header-anchor" href="#既濟之咸" aria-label="Permalink to “既濟之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>雄狐綏綏，登山崔嵬。昭告顯功，大福允興。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《咸》之《賁》。</p><h3 id="既濟之恒" tabindex="-1">既濟之恒 <a class="header-anchor" href="#既濟之恒" aria-label="Permalink to “既濟之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>火起吾後，喜炙我廡。蒼龍銜水，泉噀屋柱。雖憂無咎。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《兌》。我，宋元本作倉，依汲古。銜，汲古作含，屋作吾，均依宋元本。泉噀，宋元本作潠註，汲古作深噀，依《噬嗑》之《兌》校。</p><h3 id="既濟之遯" tabindex="-1">既濟之遯 <a class="header-anchor" href="#既濟之遯" aria-label="Permalink to “既濟之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>危坐至暮，請求不得。膏澤不降，政戻民忒。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《頤》。</p><h3 id="既濟之大壯" tabindex="-1">既濟之大壯 <a class="header-anchor" href="#既濟之大壯" aria-label="Permalink to “既濟之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>孟春和氣，鷹隼搏鷙，眾雀憂憒。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為長、為春，兌悅，故曰和氣。伏艮為鷹隼、為雀，伏坤為眾，故曰眾雀。坤為憂。</p><h3 id="既濟之晉" tabindex="-1">既濟之晉 <a class="header-anchor" href="#既濟之晉" aria-label="Permalink to “既濟之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>緩怯長姦，不能理冤。沈湎失節，君受其患。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為法，坤柔，故曰緩法。坎為姦、為冤、為酒，故曰沈湎。艮為節，坎失，故曰失節。震為君，二至四震覆，坤為患，故曰君受其患。○能，宋元本作肯，沈作浮，均依汲古。湎，宋元本作沈，汲古訛酒，依局本。</p><h3 id="既濟之明夷" tabindex="-1">既濟之明夷 <a class="header-anchor" href="#既濟之明夷" aria-label="Permalink to “既濟之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>魚鱉貪餌，死於網鉤。受危因寵，為身殃咎。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為魚，離為鱉，震為餌，離為網，坎為矯輮，故為鉤。坎為危，震為寵，坎震連，故曰受危因寵。坤為身、為殃咎。○鉤，汲古作釣，依宋元本。因，宋元本作國，依汲古。</p><h3 id="既濟之家人" tabindex="-1">既濟之家人 <a class="header-anchor" href="#既濟之家人" aria-label="Permalink to “既濟之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>金精耀怒，帶劍過午。徘徊高庫，宿於山谷。兩虎相拒，弓弩滿野。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《泰》及《震》之《豫》。耀，宋元本作輝，依汲古。庫，汲古作原，依宋元本。高庫，地名。</p><h3 id="既濟之睽" tabindex="-1">既濟之睽 <a class="header-anchor" href="#既濟之睽" aria-label="Permalink to “既濟之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>四目相望，稍近同光，並坐鼓簧。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>離為目，兌西，數四，故曰四目，重離，故曰相望、曰同光。兌為舌，故曰簧。</p><h3 id="既濟之蹇" tabindex="-1">既濟之蹇 <a class="header-anchor" href="#既濟之蹇" aria-label="Permalink to “既濟之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>茹芝餌黃，塗飲玉英。與神流通，長無憂凶。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《旅》之《復》。塗飲，依校，各本作飲酒。</p><h3 id="既濟之解" tabindex="-1">既濟之解 <a class="header-anchor" href="#既濟之解" aria-label="Permalink to “既濟之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>求獐嘉鄉，惡蛇不行。道出岐口，復反其床。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蛇、為床，震為行、為道、為口、為反，獐、岐似用半艮象。○道出岐口，汲古作豳岐口還，依宋本，元本岐作歧。復反，宋元本作還復，依汲古。</p><h3 id="既濟之損" tabindex="-1">既濟之損 <a class="header-anchor" href="#既濟之損" aria-label="Permalink to “既濟之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>天門地戶，幽冥不睹，不知所在。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮為天、為門，在戌亥，《乾鑿度》以戌亥為天門，以辰巳為地戶，兌在辰巳，故曰天門地戶。坤為地、為戶也。坤黑，故曰幽冥不睹。○睹，汲古作觀，依宋元本。此林皆言先天卦位。</p><h3 id="既濟之益" tabindex="-1">既濟之益 <a class="header-anchor" href="#既濟之益" aria-label="Permalink to “既濟之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>跛足息肩，有所忌難。金城鐵郭，以銅為關。藩屏自衛，安止無患。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《遯》之《旅》。</p><h3 id="既濟之夬" tabindex="-1">既濟之夬 <a class="header-anchor" href="#既濟之夬" aria-label="Permalink to “既濟之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>三雁俱飛，欲歸稻池。經涉萑澤，為矢所射，傷我胸臆。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>萑，宋元本作雚，汲古作山，依《屯》之《旅》校。</p><h3 id="既濟之姤" tabindex="-1">既濟之姤 <a class="header-anchor" href="#既濟之姤" aria-label="Permalink to “既濟之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>濟深難渡，濡我衣褲。五子善棹，脫無他故。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為水、為濟，重坤，故曰深。乾為衣，巽為褲，數五，故曰五子。震為子、為棹、為脫。○五，汲古作王，依宋元本。</p><h3 id="既濟之萃" tabindex="-1">既濟之萃 <a class="header-anchor" href="#既濟之萃" aria-label="Permalink to “既濟之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>飲酒作酗，跳起爭鬬。伯傷叔僵，東家治喪。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《鼎》。</p><h3 id="既濟之升" tabindex="-1">既濟之升 <a class="header-anchor" href="#既濟之升" aria-label="Permalink to “既濟之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>跛躓未起，失利後市。蒙被殃咎，不得鹿子。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳前第二句。宋元本作後失利市，依汲古。殃咎，宋本作咎殃，依元本。宋元本無末句，依汲古。</p><h3 id="既濟之困" tabindex="-1">既濟之困 <a class="header-anchor" href="#既濟之困" aria-label="Permalink to “既濟之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>辰次降婁，建星中堅。子無遠行，外顛霄陷。遂命訖終。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>降婁九月辰次，伏艮，居戌，艮為星，《月令》孟秋之月，建星昬中。兌為秋。降婁，伏象。艮建星，本象兌也。伏震為子、為行，艮止，故曰無行。外顛句有訛字。巽為命，困三至上互大過，大過死，故曰訖終。○命，汲古訛合，從宋元本。</p><h3 id="既濟之井" tabindex="-1">既濟之井 <a class="header-anchor" href="#既濟之井" aria-label="Permalink to “既濟之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>商風召寇，來呼外盜。間牒內應，與我爭鬬。殫己寶藏，主人不勝。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《革》。</p><h3 id="既濟之革" tabindex="-1">既濟之革 <a class="header-anchor" href="#既濟之革" aria-label="Permalink to “既濟之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>甘露醴泉，太平機關。仁德感應，歲樂民安。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《謙》。</p><h3 id="既濟之鼎" tabindex="-1">既濟之鼎 <a class="header-anchor" href="#既濟之鼎" aria-label="Permalink to “既濟之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>祭仲子突，要門逐忽。禍起子商，弟代其兄，鄭文不昌。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>《左傳桓十一年》宋人執鄭祭仲與之盟，以厲公歸而立之，鄭忽出奔衛。禍起子商者，謂禍起於宋也，或謂子應作於，非也。哀九年不利子商，註：子商，謂宋，宋，子姓，商後，故曰子商。厲公名突，鄭忽之弟，故曰弟代其兄。忽，即昭公。昭，明也，文也。故曰鄭文不昌。鼎通屯。上坎為仲，本卦兌剛魯，故曰子突。艮為門，震為逐、為子，震為兄，在下坎為弟，居五爻君位，故曰弟代其兄。坤為文、為鄭，坤喪，故不昌。○忽，汲古訛急，商訛傷，均依宋元本。代，宋元本訛伐，文訛久，均依汲古。</p><h3 id="既濟之震" tabindex="-1">既濟之震 <a class="header-anchor" href="#既濟之震" aria-label="Permalink to “既濟之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>反孼難步，留不及舍。露宿澤陂，亡其襦褲。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>《左傳昭十年》蘊利生孼。孼，害也，疾病也。反孼難步者，言身反向後，不能步也。艮為舍，艮止，故留不及舍。坎為露、為宿、為澤陂，巽為襦褲，襦褲，皆裡衣。巽象伏不見，故曰亡。○及舍，宋元本作反舍，依汲古。</p><h3 id="既濟之艮" tabindex="-1">既濟之艮 <a class="header-anchor" href="#既濟之艮" aria-label="Permalink to “既濟之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>虎狼結謀，相聚為保。伺候牛羊，病我商人。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《宋》。</p><h3 id="既濟之漸" tabindex="-1">既濟之漸 <a class="header-anchor" href="#既濟之漸" aria-label="Permalink to “既濟之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>明德克敏，重華貢舉。放勛徵用，八哲蒙佑。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>伏兌為華，兌卦數二，故曰重華。八哲，八元，八愷也。艮後天數八。○徵，汲古訛御，依宋元本。</p><h3 id="既濟之歸妹" tabindex="-1">既濟之歸妹 <a class="header-anchor" href="#既濟之歸妹" aria-label="Permalink to “既濟之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>貧鬼守門，日破我盆。毀罌傷瓶，空虛無子。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《剝》。</p><h3 id="既濟之豐" tabindex="-1">既濟之豐 <a class="header-anchor" href="#既濟之豐" aria-label="Permalink to “既濟之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>天命赤烏，與兵徼期。征伐無道，箕子游遨。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>《史記》武王觀兵盟津，有火至於王屋，流為烏，其色赤，其聲魄雲。離為烏，離南方，故曰赤烏。伏艮為天，巽為命，故曰天命。艮為兵、為時。徼期者，言赤烏之瑞與兵事相應也。震為征伐、為箕子、為遨游。○與或作興。</p><h3 id="既濟之旅" tabindex="-1">既濟之旅 <a class="header-anchor" href="#既濟之旅" aria-label="Permalink to “既濟之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>威約拘囚，為人所誣。皋陶平理，剖械出牢。脫歸家閭。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>伏震為威，巽繩為約，艮為拘囚，正反兌口，故曰為人所誣。艮為皋陶，伏坎為械、為牢，震在坎下，故曰剖械出牢、曰脫歸家閭。艮為家也。</p><h3 id="既濟之巽" tabindex="-1">既濟之巽 <a class="header-anchor" href="#既濟之巽" aria-label="Permalink to “既濟之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>羊驚虎狼，聳耳群聚。無益威強，為齒所傷。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《坎》之《臨》。皆以兌為耳。</p><h3 id="既濟之兌" tabindex="-1">既濟之兌 <a class="header-anchor" href="#既濟之兌" aria-label="Permalink to “既濟之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>初雖啼號，後必慶笑。光明照耀，百喜如意。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>兌口，故啼號。伏震為後、為笑，互離，故曰光明照耀。震為百喜。○喜，汲古訛嘉，依宋元本。</p><h3 id="既濟之渙" tabindex="-1">既濟之渙 <a class="header-anchor" href="#既濟之渙" aria-label="Permalink to “既濟之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>馬服長股，宜行善市。蒙佑楷耦，獲金五倍。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>《詩鄭風》兩服上襄，《箋》兩服，中央夾轅者。震為車、為駕，故曰馬服。巽為股、為長。長股，鼄也。鼄亦巽象也。巽為市，艮為金，巽為倍，卦數五，故曰獲金五倍、股長善走。</p><h3 id="既濟之節" tabindex="-1">既濟之節 <a class="header-anchor" href="#既濟之節" aria-label="Permalink to “既濟之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>應門內崩，誅賢殺暴。上下咸悖，景公失位。長歸元洹，望妻不來。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>《詩大雅》乃立應門《箋》：諸侯之宮外門曰皋門，朝門曰應門。兌毀，二三四艮覆，艮為門，故曰應門內崩。兌為斧，故曰誅賢殺暴。艮上澤下，二至五正反艮，故曰上下咸悖，言相反也。艮納丙，故曰景。景，日也。震為公，坎為失，故曰景公失位。○崩，元本作萌，依宋本、汲古。元洹，宋元本作無恆，依汲古。</p><h3 id="既濟之中孚" tabindex="-1">既濟之中孚 <a class="header-anchor" href="#既濟之中孚" aria-label="Permalink to “既濟之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>執斧破薪，使媒求婦。和合二姓，親御飲酒。色比毛嬙，姑悅公喜。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>詳《小過》之《益》。和，汲古作好，依宋元本。酒，宋元本作須，依汲古。末句元本作姑公悅喜，依宋本、汲古。</p><h3 id="既濟之小過" tabindex="-1">既濟之小過 <a class="header-anchor" href="#既濟之小過" aria-label="Permalink to “既濟之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>兩輪日轉，南上大阪。四馬共轅，無有險難，與禹笑言。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《需》。</p><h3 id="既濟之既濟" tabindex="-1">既濟之既濟 <a class="header-anchor" href="#既濟之既濟" aria-label="Permalink to “既濟之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>玄兔指掌，相與相恃。證訊詰問，誣情自直。宛死誰告，口為身禍。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>多用半象。指，汲古作捐，恃作視，誣作註，直作侶，宛死誰告作死誣難告，均依宋元本。</p><h3 id="既濟之未濟" tabindex="-1">既濟之未濟 <a class="header-anchor" href="#既濟之未濟" aria-label="Permalink to “既濟之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>千柱百梁，終不傾僵，周宗寧康。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《未濟》。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
